function solve(arr) {
  const a = [...arr] // salin supaya array asli tidak berubah
  for (let i = 1; i < a.length; i++) {
    const key = a[i] // elemen yang akan disisipkan
    let j = i - 1
    // Geser elemen yang lebih besar dari key satu langkah ke kanan.
    while (j >= 0 && a[j] > key) {
      a[j + 1] = a[j]
      j--
    }
    a[j + 1] = key // taruh key di celah yang tersisa
  }
  return a
}
